 "content": "def transform(grid):
    """Fill the smaller panel with the color shared by the two panels."""
    h, w = len(grid), len(grid[0])
    # Locate the full-width/full-height separator.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep = ("row", r, grid[r][0])
            break
    if sep is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1:
                sep = ("col", c, grid[0][c])
                break
    if sep is None:
        raise ValueError("No uniform separator found")
    axis, i, separator_color = sep
    if axis == "row":
        a = [row[:] for row in grid[:i]]
        b = [row[:] for row in grid[i+1:]]
    else:
        a = [row[:i] for row in grid]
        b = [row[i+1:] for row in grid]
    colors_a = {v for row in a for v in row if v != separator_color}
    colors_b = {v for row in b for v in row if v != separator_color}
    common = colors_a & colors_b
    if len(common) != 1:
        raise ValueError(f"Expected one shared color, found {common}")
    color = next(iter(common))
    return [[color for _ in row] for row in a]
